import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 B,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 outH,
    .param .u32 outW,
    .param .u32 kH,
    .param .u32 stride,
    .param .u32 pad,
    .param .u32 dilation
)
{
    .reg .pred p_ret, p_tmp, p_xlow, p_xhigh, p_x_oob, p_y_low, p_y_high, p_y_oob, p_skip, p_has_bias;
    .reg .u32 rB, rC, rH, rW, rOH, rOW, rKH, rSTR, rPAD, rDIL;
    .reg .u32 tidx, tidy, bdimx, bdimy, cta_x, cta_y, cta_z;
    .reg .u32 out_x, out_y, bc, bc_max, b, c, ky;
    .reg .s32 sH, sW, sPAD, nPAD, sSTR, sDIL, out_x_s32, out_y_s32, in_x, in_y_base, in_y, ky_s32;
    .reg .f32 fsum, fval_in, fval_w, fbias;
    .reg .u64 pin, pwt, pbias, pout;
    .reg .u64 off_in_b, off_wt_b, off_out_b;
    .reg .u64 t64a, t64b, bc64, oh64, ow64, oy64, ox64, h64, w64, y64, x64, kh64, c64, ky64;
    // Load params
    ld.param.u64 pin,   [in_ptr];
    ld.param.u64 pwt,   [wt_ptr];
    ld.param.u64 pbias, [bias_ptr];
    ld.param.u64 pout,  [out_ptr];
    ld.param.u32 rB,  [B];
    ld.param.u32 rC,  [C];
    ld.param.u32 rH,  [H];
    ld.param.u32 rW,  [W];
    ld.param.u32 rOH, [outH];
    ld.param.u32 rOW, [outW];
    ld.param.u32 rKH, [kH];
    ld.param.u32 rSTR,[stride];
    ld.param.u32 rPAD,[pad];
    ld.param.u32 rDIL,[dilation];
    // Thread and block indices
    mov.u32 tidx, %tid.x;
    mov.u32 tidy, %tid.y;
    mov.u32 bdimx, %ntid.x;
    mov.u32 bdimy, %ntid.y;
    mov.u32 cta_x, %ctaid.x;
    mov.u32 cta_y, %ctaid.y;
    mov.u32 cta_z, %ctaid.z;
    mad.lo.u32 out_x, cta_x, bdimx, tidx; // out_x = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.u32 out_y, cta_y, bdimy, tidy; // out_y = blockIdx.y * blockDim.y + threadIdx.y
    // Bounds check on out_x, out_y
    setp.ge.u32 p_tmp, out_x, rOW;
    @p_tmp bra RET;
    setp.ge.u32 p_tmp, out_y, rOH;
    @p_tmp bra RET;
    // bc checks
    mov.u32 bc, cta_z;
    mul.lo.u32 bc_max, rB, rC;
    setp.ge.u32 p_tmp, bc, bc_max;
    @p_tmp bra RET;
    // Split bc into b and c
    div.u32 b, bc, rC;
    rem.u32 c, bc, rC;
    // Convert to signed where needed
    cvt.s32.u32 out_x_s32, out_x;
    cvt.s32.u32 out_y_s32, out_y;
    cvt.s32.u32 sH, rH;
    cvt.s32.u32 sW, rW;
    cvt.s32.u32 sSTR, rSTR;
    cvt.s32.u32 sPAD, rPAD;
    cvt.s32.u32 sDIL, rDIL;
    // Compute in_x and in_y_base
    neg.s32 nPAD, sPAD;
    mad.lo.s32 in_x, out_x_s32, sSTR, nPAD;        // in_x = out_x*stride - pad
    mad.lo.s32 in_y_base, out_y_s32, sSTR, nPAD;   // in_y_base = out_y*stride - pad
    // Check in_x bounds once (since kw=1)
    setp.lt.s32 p_xlow,  in_x, 0;
    setp.ge.s32 p_xhigh, in_x, sW;
    or.pred p_x_oob, p_xlow, p_xhigh;
    // Initialize sum
    mov.f32 fsum, 0f00000000;
    // Loop over ky in [0, kH)
    mov.u32 ky, 0;
LOOP_KY:
    setp.ge.u32 p_tmp, ky, rKH;
    @p_tmp bra LOOP_END;
    // Compute current in_y = in_y_base + ky * dilation
    cvt.s32.u32 ky_s32, ky;
    mad.lo.s32 in_y, ky_s32, sDIL, in_y_base;
    // Check in_y bounds
    setp.lt.s32 p_y_low,  in_y, 0;
    setp.ge.s32 p_y_high, in_y, sH;
    or.pred p_y_oob, p_y_low, p_y_high;
    // Skip accumulation if either x or y out-of-bounds
    or.pred p_skip, p_x_oob, p_y_oob;
    @p_skip bra SKIP_ACCUM;
    // Load input value: x[b, c, in_y, in_x]
    // Compute offset_in_elements = (((b*C + c)*H + in_y)*W + in_x)
    // part1 = b*C + c
    {
        .reg .u32 bc_base_u32;
        mul.lo.u32 bc_base_u32, b, rC;
        add.u32 bc_base_u32, bc_base_u32, c;
        cvt.u64.u32 bc64, bc_base_u32;
        cvt.u64.u32 h64, rH;
        cvt.u64.u32 w64, rW;
        // t64a = bc64 * H
        mul.lo.u64 t64a, bc64, h64;
        // add in_y
        cvt.u64.s32 y64, in_y;
        add.u64 t64a, t64a, y64;
        // t64a = t64a * W
        mul.lo.u64 t64a, t64a, w64;
        // add in_x
        cvt.u64.s32 x64, in_x;
        add.u64 t64a, t64a, x64;
        // bytes
        shl.b64 off_in_b, t64a, 2;
    }
    // Load input
    add.u64 t64a, pin, off_in_b;
    ld.global.f32 fval_in, [t64a];
    // Load weight: w[c, 0, ky, 0] -> offset = c*kH + ky
    {
        cvt.u64.u32 c64, c;
        cvt.u64.u32 kh64, rKH;
        mul.lo.u64 t64b, c64, kh64;
        cvt.u64.u32 ky64, ky;
        add.u64 t64b, t64b, ky64;
        shl.b64 off_wt_b, t64b, 2;
    }
    add.u64 t64b, pwt, off_wt_b;
    ld.global.f32 fval_w, [t64b];
    // Accumulate
    fma.rn.f32 fsum, fval_in, fval_w, fsum;
SKIP_ACCUM:
    add.u32 ky, ky, 1;
    bra LOOP_KY;
LOOP_END:
    // Add bias if provided (bias_ptr != 0)
    setp.ne.u64 p_has_bias, pbias, 0;
    @!p_has_bias bra NO_BIAS;
    {
        cvt.u64.u32 c64, c;
        shl.b64 t64b, c64, 2;
        add.u64 t64a, pbias, t64b;
        ld.global.f32 fbias, [t64a];
        add.f32 fsum, fsum, fbias;
    }
NO_BIAS:
    // Store to output: y[b, c, out_y, out_x]
    {
        // offset_out_elements = (((b*C + c)*outH + out_y)*outW + out_x)
        .reg .u32 bc_base2;
        mul.lo.u32 bc_base2, b, rC;
        add.u32 bc_base2, bc_base2, c;
        cvt.u64.u32 bc64, bc_base2;
        cvt.u64.u32 oh64, rOH;
        cvt.u64.u32 ow64, rOW;
        cvt.u64.u32 oy64, out_y;
        cvt.u64.u32 ox64, out_x;
        mul.lo.u64 t64a, bc64, oh64;
        add.u64 t64a, t64a, oy64;
        mul.lo.u64 t64a, t64a, ow64;
        add.u64 t64a, t64a, ox64;
        shl.b64 off_out_b, t64a, 2;
    }
    add.u64 t64a, pout, off_out_b;
    st.global.f32 [t64a], fsum;
RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        # Depthwise Conv2d weights: (C, 1, kH, 1)
        weight = torch.empty(in_channels, 1, kernel_size, 1, dtype=torch.float32)
        init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)
        if bias:
            bias_t = torch.empty(in_channels, dtype=torch.float32)
            fan_in = 1 * kernel_size * 1
            bound = 1 / math.sqrt(fan_in)
            init.uniform_(bias_t, -bound, bound)
            self.bias = nn.Parameter(bias_t)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        B, C, H, W = x.shape
        assert C == self.in_channels, "Channel count mismatch"
        kH = self.kernel_size
        stride = self.stride
        pad = self.padding
        dil = self.dilation

        # Output dimensions (kernel_w = 1)
        outH = (H + 2 * pad - dil * (kH - 1) - 1) // stride + 1
        outW = (W + 2 * pad - 1) // stride + 1

        y = torch.empty((B, C, outH, outW), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        # Grid/block configuration
        block_x = 16
        block_y = 16
        grid_x = (outW + block_x - 1) // block_x
        grid_y = (outH + block_y - 1) // block_y
        grid_z = B * C

        bias_arg = self.bias if self.bias is not None else u64(0)

        module.launch(
            "the_entry_name",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[
                x,                       # in_ptr (.u64)
                self.weight,             # wt_ptr (.u64)
                bias_arg,                # bias_ptr (.u64) or 0
                y,                       # out_ptr (.u64)
                u32(B),
                u32(C),
                u32(H),
                u32(W),
                u32(outH),
                u32(outW),
                u32(kH),
                u32(stride),
                u32(pad),
                u32(dil),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return y

